/** C: include/mondata.h — the `slimeproof(ptr)` macro body */
export function slimeproof(ptr) {
    return (cptr.eq((ptr), cptr.add(mons, NHC.PM_GREEN_SLIME, $sizeof_permonst)) ||
        (cptr.eq((ptr), cptr.add(mons, NHC.PM_FIRE_VORTEX, $sizeof_permonst)) ||
            cptr.eq((ptr), cptr.add(mons, NHC.PM_FLAMING_SPHERE, $sizeof_permonst)) ||
            cptr.eq((ptr), cptr.add(mons, NHC.PM_FIRE_ELEMENTAL, $sizeof_permonst)) ||
            cptr.eq((ptr), cptr.add(mons, NHC.PM_SALAMANDER, $sizeof_permonst))) ||
        (cptr.ld1so((ptr), $permonst_mlet) == NHC.S_GHOST)
        ? 1
        : 0);
}

/** C: include/engrave.h — the `spot_shows_engravings(x, y)` macro body */
export function spot_shows_engravings(x, y) {
    return (cptr.ld1so3(
        svl,
        (x),
        $sizeof_rm_x21,
        (y),
        $sizeof_rm,
        $instance_globals_saved_l_level + $rm_typ
    ) ==
        NHC.CORR ||
        cptr.ld1so3(
            svl,
            (x),
            $sizeof_rm_x21,
            (y),
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_typ
        ) ==
            NHC.ICE ||
        cptr.ld1so3(
            svl,
            (x),
            $sizeof_rm_x21,
            (y),
            $sizeof_rm,
            $instance_globals_saved_l_level + $rm_typ
        ) ==
            NHC.ROOM
        ? 1
        : 0);
}

/** C: include/obj.h — the `stone_missile(o)` macro body */
export function stone_missile(o) {
    return ((((cptr.ldI32o2(
        objects,
        cptr.ldI16o((o), $obj_otyp),
        $sizeof_objclass,
        $objclass_oc_material
    ) & 31) | 0) ==
        NHC.GEMSTONE ||
        (((cptr.ldI32o2(
            objects,
            cptr.ldI16o((o), $obj_otyp),
            $sizeof_objclass,
            $objclass_oc_material
        ) & 31) | 0) ==
            NHC.MINERAL)) &&
        cptr.ld1so((o), $obj_oclass) != NHC.RING_CLASS
        ? 1
        : 0);
}

