/** C: include/mondata.h — the `vegan(ptr)` macro body */
export function vegan(ptr) {
    return (cptr.ld1so((ptr), $permonst_mlet) == NHC.S_BLOB ||
        cptr.ld1so((ptr), $permonst_mlet) == NHC.S_JELLY ||
        cptr.ld1so((ptr), $permonst_mlet) == NHC.S_FUNGUS ||
        cptr.ld1so((ptr), $permonst_mlet) == NHC.S_VORTEX ||
        cptr.ld1so((ptr), $permonst_mlet) == NHC.S_LIGHT ||
        (cptr.ld1so((ptr), $permonst_mlet) == NHC.S_ELEMENTAL &&
            !cptr.eq((ptr), cptr.add(mons, NHC.PM_STALKER, $sizeof_permonst))) ||
        (cptr.ld1so((ptr), $permonst_mlet) == NHC.S_GOLEM &&
            !cptr.eq((ptr), cptr.add(mons, NHC.PM_FLESH_GOLEM, $sizeof_permonst)) &&
            !cptr.eq((ptr), cptr.add(mons, NHC.PM_LEATHER_GOLEM, $sizeof_permonst))) ||
        (cptr.ld1so((ptr), $permonst_mlet) == NHC.S_GHOST)
        ? 1
        : 0);
}

